'use client';

import Link from 'next/link';
import { useState, type ReactNode } from 'react';
import { MethodologyCard } from '@/components/result/MethodologyCard';
import { ReportSummary } from '@/components/result/ReportSummary';
import { SectionNav, type NavSection } from '@/components/result/SectionNav';
import {
  classifySkillCategory,
  enrichResult,
  parseResource,
  PRIORITY_META,
  SKILL_CATEGORY_LABEL,
  TASK_CHANGE_LABEL,
  type EnrichedRole,
  type ScheduledStep,
} from '@/lib/result-insights';
import type { AnalyzeResponse, TaskChangeType } from '@/lib/types';

const SECTIONS: NavSection[] = [
  { id: 'summary', label: '摘要' },
  { id: 'skills', label: '技能画像' },
  { id: 'tasks', label: '任务变化' },
  { id: 'roles', label: '岗位方向' },
  { id: 'gaps', label: '技能差距' },
  { id: 'plan', label: '学习计划' },
  { id: 'sdg', label: 'SDG' },
  { id: 'method', label: '方法与来源' },
];

type ResultDashboardProps = {
  result: AnalyzeResponse;
  weeklyStudyHours: number;
  toolbar?: ReactNode;
};

export function ResultDashboard({ result, weeklyStudyHours, toolbar }: ResultDashboardProps) {
  const view = enrichResult(result, weeklyStudyHours);
  const [highRiskOnly, setHighRiskOnly] = useState(false);
  const [showAllRoles, setShowAllRoles] = useState(false);

  const neededBySkill = new Map(view.gaps.map((gap) => [gap.skill, gap.neededBy] as const));
  const topRole = view.roles[0] ?? null;
  const firstGap = view.gaps.find((gap) => gap.status === 'gap');

  const visibleTasks = highRiskOnly
    ? view.tasks.filter((task) => task.changeType === 'automated')
    : view.tasks;
  const visibleRoles = showAllRoles ? view.roles : view.roles.slice(0, 3);

  const conclusion =
    `已识别 ${view.metrics.skillCount} 项技能，其中 ${view.metrics.strengthCount} 项可直接迁移；` +
    (firstGap ? `建议优先补齐「${firstGap.skill}」，` : '') +
    `按每周 ${weeklyStudyHours} 小时计算，全部学习步骤约需 ${view.metrics.totalWeeks} 周。`;

  return (
    <main className="mx-auto w-full max-w-6xl px-4 pb-16 pt-10 sm:pt-14">
      <header className="mb-2 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div className="max-w-2xl">
          <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-[#0e7c57]">
            AI 技能转型导航
          </p>
          <h1 className="mt-1.5 text-2xl font-semibold tracking-tight text-[#0f241d] sm:text-3xl">
            转型建议报告
          </h1>
          <p className="mt-2 text-sm leading-6 text-[#43554c]">
            基于你提交的岗位、任务与学习投入生成的示例报告，所有分数与工时为估算值。
          </p>
        </div>

        <div className="no-print flex flex-wrap items-center gap-2">
          <span className="badge badge-neutral">示例数据</span>
          <button
            type="button"
            onClick={() => window.print()}
            className="rounded-full border border-[rgba(16,40,32,0.18)] bg-white/70 px-3 py-1.5 text-xs font-medium text-[#43554c] transition hover:border-[#0e7c57] hover:text-[#0e7c57]"
          >
            打印 / 另存 PDF
          </button>
          <Link
            href="/"
            className="rounded-full border border-[rgba(16,40,32,0.18)] bg-white/70 px-3 py-1.5 text-xs font-medium text-[#43554c] transition hover:border-[#0e7c57] hover:text-[#0e7c57]"
          >
            重新填写
          </Link>
        </div>
      </header>

      {toolbar}

      <SectionNav sections={SECTIONS} />

      <div className="mt-5 space-y-5">
        <ReportSummary metrics={view.metrics} topRole={topRole} conclusion={conclusion} />

        {/* 技能画像 */}
        <SectionCard id="skills" title="技能画像" badge={`${view.skills.length} 项`}>
          {view.categoryCounts.length > 0 && (
            <div className="mb-4 space-y-2">
              {view.categoryCounts.map((item) => (
                <div key={item.category} className="flex items-center gap-3">
                  <span className="w-24 shrink-0 text-[11px] text-[#788b82]">{item.label}</span>
                  <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-[rgba(16,40,32,0.07)]">
                    <div
                      className="h-full rounded-full bg-[#0e7c57]"
                      style={{ width: `${(item.count / Math.max(1, view.skills.length)) * 100}%` }}
                    />
                  </div>
                  <span className="w-8 shrink-0 text-right text-[11px] text-[#43554c] tnum">
                    {item.count}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="grid gap-3 sm:grid-cols-2">
            {view.skills.map((skill) => (
              <div key={skill.name} className="glass-sub p-4">
                <div className="flex items-start justify-between gap-2">
                  <p className="text-sm font-semibold text-[#0f241d]">{skill.name}</p>
                  <span className="badge badge-neutral">
                    {SKILL_CATEGORY_LABEL[classifySkillCategory(skill.name)]}
                  </span>
                </div>
                <p className="mt-1.5 text-xs leading-5 text-[#788b82]">{skill.evidence}</p>
                <p className="mt-2 text-[11px] text-[#788b82]">
                  <span className="tnum font-semibold text-[#0e7c57]">
                    {neededBySkill.get(skill.name) ?? 0}
                  </span>{' '}
                  个推荐方向需要
                </p>
              </div>
            ))}
          </div>
        </SectionCard>

        {/* 任务变化 */}
        <SectionCard
          id="tasks"
          title="任务变化"
          badge={`${view.tasks.length} 项任务`}
          action={
            <button
              type="button"
              onClick={() => setHighRiskOnly((prev) => !prev)}
              aria-pressed={highRiskOnly}
              className={`no-print rounded-full border px-3 py-1 text-[11px] font-medium transition ${
                highRiskOnly
                  ? 'border-[#b4482f] bg-[rgba(196,84,63,0.08)] text-[#b4482f]'
                  : 'border-[rgba(16,40,32,0.18)] bg-white/60 text-[#43554c] hover:border-[#0e7c57]'
              }`}
            >
              只看高风险
            </button>
          }
        >
          <TaskDistribution distribution={view.taskDistribution} total={view.tasks.length} />

          <ul className="mt-4 space-y-3">
            {visibleTasks.map((item) => (
              <li key={item.task} className="glass-sub print-break p-4">
                <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                  <div className="lg:max-w-sm">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="text-sm font-medium text-[#0f241d]">{item.task}</p>
                      <span className={`badge ${changeTone(item.changeType)}`}>
                        {TASK_CHANGE_LABEL[item.changeType]}
                      </span>
                    </div>
                    <a
                      href={item.source.url}
                      target="_blank"
                      rel="noreferrer"
                      className="mt-1 inline-flex items-center gap-1 text-xs text-[#788b82] underline-offset-2 transition hover:text-[#0e7c57] hover:underline"
                    >
                      {item.source.name} · {item.source.date}
                      <span aria-hidden="true">↗</span>
                    </a>
                  </div>
                  <div className="grid w-full gap-3 sm:grid-cols-2 lg:max-w-md">
                    <Meter label="AI 影响" value={item.aiImpact} tone="accent" />
                    <Meter label="人类判断" value={item.humanJudgment} tone="gold" />
                  </div>
                </div>
              </li>
            ))}
            {visibleTasks.length === 0 && (
              <li className="glass-sub p-4 text-xs text-[#788b82]">
                当前没有符合筛选条件的任务。
              </li>
            )}
          </ul>
        </SectionCard>

        {/* 相邻岗位 */}
        <SectionCard
          id="roles"
          title="相邻岗位"
          badge={`${view.roles.length} 个方向`}
          action={
            view.roles.length > 3 ? (
              <button
                type="button"
                onClick={() => setShowAllRoles((prev) => !prev)}
                aria-expanded={showAllRoles}
                className="no-print rounded-full border border-[rgba(16,40,32,0.18)] bg-white/60 px-3 py-1 text-[11px] font-medium text-[#43554c] transition hover:border-[#0e7c57] hover:text-[#0e7c57]"
              >
                {showAllRoles ? '收起' : `展开全部 ${view.roles.length} 个`}
              </button>
            ) : null
          }
        >
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
            {visibleRoles.map((role) => (
              <RoleCard key={role.title} role={role} />
            ))}
          </div>
          <p className="mt-4 text-[11px] leading-5 text-[#788b82]">
            匹配分 = 技能重合度 + 兴趣 / 经验 / 岗位方向的小幅调整，仅用于排序，不代表录用概率。
          </p>
        </SectionCard>

        <div className="grid gap-5 lg:grid-cols-2">
          {/* 技能差距 */}
          <SectionCard
            id="gaps"
            title="技能差距"
            badge={`${view.metrics.gapCount} 项待补`}
            className="h-full"
          >
            <div className="mb-3 flex flex-wrap gap-2 text-[11px] text-[#788b82]">
              <span>
                待补{' '}
                <span className="font-semibold text-[#b4482f] tnum">{view.metrics.gapCount}</span> 项
              </span>
              <span aria-hidden="true">·</span>
              <span>
                优势{' '}
                <span className="font-semibold text-[#0e7c57] tnum">
                  {view.metrics.strengthCount}
                </span>{' '}
                项
              </span>
            </div>

            <ul className="space-y-2">
              {view.gaps.map((gap) => {
                const meta = PRIORITY_META[gap.priority];
                return (
                  <li
                    key={gap.skill}
                    className="glass-sub flex items-center justify-between gap-3 px-3 py-2.5"
                  >
                    <div className="flex min-w-0 items-center gap-2.5">
                      <span
                        className={`status-dot ${
                          gap.status === 'gap' ? 'status-gap' : 'status-strength'
                        }`}
                        aria-hidden="true"
                      >
                        {gap.status === 'gap' ? '↑' : '✔'}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-medium text-[#0f241d]">{gap.skill}</p>
                        <p className="text-[11px] text-[#788b82]">
                          {gap.status === 'gap' ? '待补差距' : '现有优势'} ·{' '}
                          {SKILL_CATEGORY_LABEL[gap.category]} · 被{' '}
                          <span className="tnum">{gap.neededBy}</span> 个方向需要
                        </p>
                      </div>
                    </div>
                    <span className={`badge badge-${gap.priority}`}>
                      <span aria-hidden="true">{meta.icon}</span>
                      {meta.label}
                    </span>
                  </li>
                );
              })}
            </ul>

            <p className="mt-3 text-[11px] text-[#788b82]">
              按优先级从高到低排列，现有优势 {view.metrics.strengthCount} 项。
            </p>
          </SectionCard>

          {/* 学习计划 */}
          <SectionCard
            id="plan"
            title="学习计划"
            badge={`合计 ${view.metrics.totalHours} 小时`}
            className="h-full"
          >
            <div className="mb-4 grid grid-cols-3 gap-2">
              <MiniStat label="总时长" value={`${view.metrics.totalHours} 小时`} />
              <MiniStat label="预计周数" value={`${view.metrics.totalWeeks} 周`} />
              <MiniStat label="每周投入" value={`${weeklyStudyHours} 小时`} />
            </div>

            <div className="space-y-4">
              {view.planGroups.map((group) => (
                <div key={group.phase}>
                  <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.14em] text-[#788b82]">
                    {group.phase} · 第 {group.steps[0].weekStart}–
                    {group.steps[group.steps.length - 1].weekEnd} 周
                  </p>
                  <ol className="space-y-2">
                    {group.steps.map((step, index) => (
                      <PlanRow key={step.skillGap} step={step} index={index + 1} />
                    ))}
                  </ol>
                </div>
              ))}
            </div>
          </SectionCard>
        </div>

        {/* SDG */}
        <SectionCard id="sdg" title="SDG 关联" badge={`${view.sdgs.length} 项目标`}>
          <div className="grid gap-3 md:grid-cols-3">
            {view.sdgs.map((link) => {
              const number = link.goal.match(/SDG\s*(\d+)/)?.[1] ?? '';
              return (
                <div key={link.goal} className="glass-sub p-4">
                  <div className="flex items-center gap-2">
                    <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[rgba(14,124,87,0.10)] text-[11px] font-bold text-[#0e7c57] tnum">
                      {number || 'SDG'}
                    </span>
                    <p className="text-sm font-semibold text-[#0f241d]">{link.goal}</p>
                  </div>
                  <p className="mt-2 text-xs leading-6 text-[#43554c]">{link.reason}</p>
                </div>
              );
            })}
          </div>
        </SectionCard>

        <MethodologyCard scenarioNote={view.scenarioNote} methodology={view.methodology} />
      </div>
    </main>
  );
}

/* =========================================================
 * 子组件
 * ======================================================= */

function SectionCard({
  id,
  title,
  badge,
  action,
  children,
  className = '',
}: {
  id: string;
  title: string;
  badge?: ReactNode;
  action?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  return (
    <section id={id} className={`glass section-anchor print-break p-5 sm:p-6 ${className}`}>
      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <h2 className="text-base font-semibold text-[#0f241d]">{title}</h2>
          {badge ? <span className="badge badge-neutral">{badge}</span> : null}
        </div>
        {action}
      </div>
      {children}
    </section>
  );
}

function TaskDistribution({
  distribution,
  total,
}: {
  distribution: { automated: number; augmented: number; unchanged: number };
  total: number;
}) {
  const rows = [
    { key: 'automated', label: TASK_CHANGE_LABEL.automated, color: '#b4482f' },
    { key: 'augmented', label: TASK_CHANGE_LABEL.augmented, color: '#a98545' },
    { key: 'unchanged', label: TASK_CHANGE_LABEL.unchanged, color: '#0e7c57' },
  ] as const;

  const safeTotal = Math.max(1, total);

  return (
    <div>
      <div className="flex h-2.5 overflow-hidden rounded-full bg-[rgba(16,40,32,0.07)]">
        {rows.map((row) => {
          const value = distribution[row.key];
          if (value === 0) return null;
          return (
            <span
              key={row.key}
              style={{ width: `${(value / safeTotal) * 100}%`, backgroundColor: row.color }}
              aria-hidden="true"
            />
          );
        })}
      </div>
      <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-[#788b82]">
        {rows.map((row) => (
          <span key={row.key} className="inline-flex items-center gap-1.5">
            <span
              className="inline-block h-2 w-2 rounded-full"
              style={{ backgroundColor: row.color }}
              aria-hidden="true"
            />
            {row.label}
            <span className="tnum font-semibold text-[#43554c]">{distribution[row.key]}</span>
          </span>
        ))}
      </div>
    </div>
  );
}

function RoleCard({ role }: { role: EnrichedRole }) {
  return (
    <article className="glass-sub flex flex-col p-4 transition hover:shadow-[0_10px_24px_rgba(16,40,32,0.08)]">
      <div className="flex items-start justify-between gap-2">
        <h3 className="text-sm font-semibold leading-5 text-[#0f241d]">{role.title}</h3>
        <p className="shrink-0 text-right">
          <span className="block text-2xl font-semibold tracking-tight text-[#0f241d] tnum">
            {role.matchScore}
          </span>
          <span className="block text-[10px] text-[#788b82]">匹配分</span>
        </p>
      </div>

      <div
        className="mt-2 h-1.5 overflow-hidden rounded-full bg-[rgba(16,40,32,0.07)]"
        role="progressbar"
        aria-label={`${role.title} 匹配分`}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={role.matchScore}
      >
        <div className="h-full rounded-full bg-[#0e7c57]" style={{ width: `${role.matchScore}%` }} />
      </div>

      <p className="mt-2 text-[11px] text-[#788b82]">
        技能命中{' '}
        <span className="tnum font-semibold text-[#43554c]">
          {role.matchedSkills.length}/{role.requiredCount}
        </span>{' '}
        · 待补 <span className="tnum">{role.missingSkills.length}</span> 项 · 兴趣命中{' '}
        <span className="tnum">{role.interestHitCount}</span>
      </p>

      <ul className="mt-3 space-y-1.5">
        {role.reasons.slice(0, 4).map((reason) => (
          <li key={reason} className="flex gap-2 text-xs leading-5 text-[#43554c]">
            <span className="mt-2 h-1 w-1 shrink-0 rounded-full bg-[#9fb3a8]" aria-hidden="true" />
            <span>{reason}</span>
          </li>
        ))}
      </ul>

      <div className="mt-3 space-y-2 border-t border-[rgba(16,40,32,0.08)] pt-3">
        <SkillChips label="已匹配技能" items={role.matchedSkills} tone="matched" />
        <SkillChips label="待补技能" items={role.missingSkills} tone="missing" />
      </div>
    </article>
  );
}

function SkillChips({
  label,
  items,
  tone,
}: {
  label: string;
  items: string[];
  tone: 'matched' | 'missing';
}) {
  const chipClass =
    tone === 'matched'
      ? 'border-[rgba(14,124,87,0.25)] bg-[rgba(14,124,87,0.07)] text-[#0e7c57]'
      : 'border-[rgba(196,84,63,0.25)] bg-[rgba(196,84,63,0.06)] text-[#b4482f]';

  return (
    <div>
      <p className="text-[10px] font-medium uppercase tracking-[0.1em] text-[#788b82]">{label}</p>
      <div className="mt-1 flex flex-wrap gap-1.5">
        {items.length > 0 ? (
          items.map((item) => (
            <span
              key={item}
              className={`rounded-md border px-2 py-0.5 text-[11px] font-medium ${chipClass}`}
            >
              {item}
            </span>
          ))
        ) : (
          <span className="text-[11px] text-[#788b82]">暂无</span>
        )}
      </div>
    </div>
  );
}

function PlanRow({ step, index }: { step: ScheduledStep; index: number }) {
  const resource = parseResource(step.resource);

  return (
    <li className="glass-sub flex gap-3 px-3.5 py-3">
      <span className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[#0e7c57] text-[11px] font-semibold text-white tnum">
        {index}
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium leading-5 text-[#0f241d]">
          补足 <span className="font-semibold">{step.skillGap}</span>
          <span className="ml-2 text-[11px] font-normal text-[#788b82] tnum">
            第 {step.weekStart}–{step.weekEnd} 周 · {step.estimatedHours} 小时
          </span>
        </p>
        <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-[11px] text-[#788b82]">
          <a
            href={step.resource.url}
            target="_blank"
            rel="noreferrer"
            className="font-medium text-[#0e7c57] underline-offset-2 hover:underline"
          >
            {resource.title}
            <span aria-hidden="true"> ↗</span>
          </a>
          {resource.provider ? <span>· {resource.provider}</span> : null}
          {resource.publishedAt ? <span className="tnum">· {resource.publishedAt}</span> : null}
        </div>
      </div>
    </li>
  );
}

function MiniStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="glass-sub px-2.5 py-2 text-center">
      <p className="text-[10px] text-[#788b82]">{label}</p>
      <p className="text-sm font-semibold text-[#0f241d] tnum">{value}</p>
    </div>
  );
}

function Meter({ label, value, tone }: { label: string; value: number; tone: 'accent' | 'gold' }) {
  const safeValue = Math.min(100, Math.max(0, value));
  const color = tone === 'accent' ? '#0e7c57' : '#a98545';

  return (
    <div>
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-xs text-[#788b82]">{label}</span>
        <span className="text-sm font-semibold text-[#0f241d] tnum">{safeValue}%</span>
      </div>
      <div
        className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[rgba(16,40,32,0.07)]"
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={safeValue}
      >
        <div
          className="h-full rounded-full"
          style={{ width: `${safeValue}%`, backgroundColor: color }}
        />
      </div>
    </div>
  );
}

function changeTone(type: TaskChangeType): string {
  if (type === 'automated') return 'badge-high';
  if (type === 'augmented') return 'badge-medium';
  return 'badge-low';
}
