'use client';

import { useEffect, useState } from 'react';

export type NavSection = { id: string; label: string };

type SectionNavProps = {
  sections: NavSection[];
};

export function SectionNav({ sections }: SectionNavProps) {
  const [active, setActive] = useState(sections[0]?.id ?? '');

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((entry) => entry.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
        if (visible[0]) {
          setActive(visible[0].target.id);
        }
      },
      { rootMargin: '-96px 0px -60% 0px', threshold: [0, 1] },
    );

    sections.forEach((section) => {
      const el = document.getElementById(section.id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [sections]);

  return (
    <nav
      aria-label="报告分区"
      className="no-print sticky top-3 z-20 mt-4 flex gap-1.5 overflow-x-auto rounded-full border border-white/70 bg-white/65 px-2 py-1.5 shadow-[0_10px_26px_rgba(16,40,32,0.08)] backdrop-blur-md"
    >
      {sections.map((section) => {
        const isActive = active === section.id;
        return (
          <a
            key={section.id}
            href={`#${section.id}`}
            aria-current={isActive ? 'true' : undefined}
            className={`whitespace-nowrap rounded-full px-3 py-1.5 text-xs font-medium transition ${
              isActive
                ? 'bg-[#0e7c57] text-white'
                : 'text-[#43554c] hover:bg-white hover:text-[#0f241d]'
            }`}
          >
            {section.label}
          </a>
        );
      })}
    </nav>
  );
}
