import type { EnrichedMethodology } from '@/lib/result-insights';

type MethodologyCardProps = {
  scenarioNote: string;
  methodology: EnrichedMethodology;
};

export function MethodologyCard({ scenarioNote, methodology }: MethodologyCardProps) {
  return (
    <section id="method" className="glass section-anchor print-break p-5 sm:p-6">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
        <h2 className="text-base font-semibold text-[#0f241d]">情景说明与方法</h2>
        <span className="badge badge-neutral">估计性质 · 非预测</span>
      </div>

      <p className="glass-sub px-3.5 py-3 text-sm leading-6 text-[#43554c]">{scenarioNote}</p>

      <details className="group mt-4">
        <summary className="cursor-pointer select-none text-sm font-medium text-[#0e7c57]">
          查看方法与口径
        </summary>
        <ul className="mt-3 space-y-2 text-xs leading-6 text-[#43554c]">
          <li>
            <span className="font-semibold text-[#0f241d]">匹配分：</span>
            {methodology.matchFormula}
          </li>
          <li>
            <span className="font-semibold text-[#0f241d]">技能优先级：</span>
            {methodology.priorityRule}
          </li>
          <li>
            <span className="font-semibold text-[#0f241d]">学习时长：</span>
            {methodology.durationRule}
          </li>
        </ul>
      </details>

      <div className="mt-4">
        <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.14em] text-[#788b82]">
          来源清单
        </p>
        <ul className="space-y-1.5">
          {methodology.sources.map((source) => (
            <li
              key={`${source.name}-${source.date}-${source.usedFor}`}
              className="flex flex-wrap items-baseline gap-x-2 gap-y-1 text-xs text-[#43554c]"
            >
              <span className="badge badge-neutral">{source.usedFor}</span>
              {source.url ? (
                <a
                  href={source.url}
                  target="_blank"
                  rel="noreferrer"
                  className="font-medium text-[#0e7c57] underline-offset-2 hover:underline"
                >
                  {source.name}
                  <span aria-hidden="true"> ↗</span>
                </a>
              ) : (
                <span className="font-medium text-[#0f241d]">{source.name}</span>
              )}
              <span className="tnum text-[#788b82]">{source.date}</span>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
