import type { EnrichedMetrics } from '@/lib/result-insights';

type ReportSummaryProps = {
  metrics: EnrichedMetrics;
  topRole: { title: string; matchScore: number } | null;
  conclusion: string;
};

export function ReportSummary({ metrics, topRole, conclusion }: ReportSummaryProps) {
  const tiles = [
    { label: '已识别技能', value: String(metrics.skillCount), unit: '项' },
    { label: '待补技能', value: String(metrics.gapCount), unit: '项' },
    {
      label: '最匹配方向',
      value: topRole ? topRole.title : '暂无',
      unit: topRole ? `${topRole.matchScore} 分` : '',
      small: true,
    },
    { label: '学习总量', value: String(metrics.totalHours), unit: '小时' },
    { label: '预计周数', value: String(metrics.totalWeeks), unit: '周' },
  ];

  return (
    <section id="summary" className="glass section-anchor p-5 sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-[#0e7c57]">
            Executive Summary
          </p>
          <h2 className="mt-1 text-base font-semibold text-[#0f241d]">报告摘要</h2>
        </div>
        <p className="badge badge-neutral">仅用于演示 · 非预测</p>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
        {tiles.map((tile) => (
          <div key={tile.label} className="glass-sub px-3.5 py-3">
            <p className="text-[11px] text-[#788b82]">{tile.label}</p>
            <p
              className={`mt-1 font-semibold tracking-tight text-[#0f241d] tnum ${
                tile.small ? 'text-sm leading-6' : 'text-2xl'
              }`}
            >
              {tile.value}
              {tile.unit ? (
                <span className="ml-1 text-[11px] font-normal text-[#788b82]">{tile.unit}</span>
              ) : null}
            </p>
          </div>
        ))}
      </div>

      <p className="mt-4 rounded-xl border border-[rgba(14,124,87,0.16)] bg-[rgba(14,124,87,0.06)] px-3.5 py-2.5 text-sm leading-6 text-[#2b4a3d]">
        {conclusion}
      </p>
    </section>
  );
}
